<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import Icon from './GardenIcon.vue'
import Row from './NativeRow.vue'
import Sheet from './GardenSheet.vue'
import { selectIds, toggleAll } from './listSelection.js'
import { useBoxSelection } from './useBoxSelection.js'
import { dependencies, reverseDependencies, equalOrder, dropSelection, moveSelection, nameOf, dateText, draftIssues } from './nativeModel.js'
const props=defineProps({bridge:Object,installation:Object,mods:{type:Array,default:()=>[]},currentOrder:{type:Array,default:()=>[]},currentRules:{type:Array,default:()=>[]},active:Boolean,workspaceDirty:Boolean})
const emit=defineEmits(['apply','reveal','recovery','busy'])
const items=ref([]),selected=ref(null),order=ref([]),base=ref([]),busy=ref(false),error=ref(''),notice=ref(''),query=ref(''),past=ref([]),future=ref([])
const selection=ref({list:'en',ids:[],anchor:null}),sheet=ref(null),name=ref(''),sheetMode=ref('new'),imported=ref(null),preview=ref(null),text=ref(''),menu=ref(false),pending=ref(null)
const onList=ref(null),offList=ref(null)
const marquee=useBoxSelection({getSelection:()=>selection.value,setSelection:value=>selection.value=value,canStart:()=>!busy.value&&!sheet.value&&!current.value?.legacy})
const selectionBox=marquee.rectangle
let epoch=0,drag=null,disposed=false
const dirty=computed(()=>!equalOrder(order.value,base.value))
const current=computed(()=>items.value.find(p=>p.id===selected.value))
const applied=computed(()=>equalOrder(order.value,props.currentOrder)&&JSON.stringify(current.value?.rules||[])===JSON.stringify(props.currentRules))
const byId=id=>props.mods.find(m=>m.id===id)||{id,name:id,installed:false,capabilities:[],issues:[]}
const available=computed(()=>props.mods.filter(m=>!order.value.includes(m.id)))
const matches=m=>!query.value||`${m.name} ${m.id} ${m.version} ${m.source}`.toLowerCase().includes(query.value.toLowerCase())
const enabledView=computed(()=>order.value.map(byId).filter(matches)),availableView=computed(()=>available.value.filter(matches))
const issues=computed(()=>draftIssues(order.value,props.mods))
const payload=()=>({installation_id:props.installation.installation_id})
async function request(command,args={}){return props.bridge.request(command,{...payload(),...args})}
async function refresh(preferred=selected.value){if(!props.installation)return;const token=++epoch;busy.value=true;error.value='';try{const r=await request('native.profile.list');if(token!==epoch||disposed)return;items.value=r.items||[];if(!dirty.value){const item=items.value.find(p=>p.id===preferred)||items.value[0];select(item?.id,true)}}catch(e){if(token===epoch)error.value=e.message}finally{if(token===epoch)busy.value=false}}
function select(id,force=false){if(dirty.value&&!force){pending.value={kind:'select',id};sheet.value='discard';return}const p=items.value.find(p=>p.id===id);selected.value=id||null;order.value=[...(p?.enabled_ids||[])];base.value=[...order.value];past.value=[];future.value=[];selection.value={list:'en',ids:[],anchor:null};preview.value=null;menu.value=false}
function change(next,label){if(busy.value||equalOrder(next,order.value))return;past.value.push({order:[...order.value],label});future.value=[];order.value=next}
function undo(){if(busy.value)return;const p=past.value.pop();if(p){future.value.push({order:[...order.value],label:p.label});order.value=p.order}}
function redo(){if(busy.value)return;const p=future.value.pop();if(p){past.value.push({order:[...order.value],label:p.label});order.value=p.order}}
function group(id,list){return selection.value.list===list&&selection.value.ids.includes(id)?selection.value.ids:[id]}
function toggle(id){const en=order.value.includes(id),ids=group(id,en?'en':'avail');if(en){const affected=reverseDependencies(ids,order.value,props.mods);if(affected.length){pending.value={kind:'disable',ids,affected};sheet.value='reverse';return}change(order.value.filter(x=>!ids.includes(x)),'停用')}else{const {add}=dependencies(ids,order.value,props.mods);change([...order.value,...add],'启用')} }
function pick(mod,list,event){selection.value=selectIds(selection.value,list,mod.id,(list==='en'?enabledView.value:availableView.value).map(m=>m.id),event);(list==='en'?onList.value:offList.value)?.focus({preventScroll:true})}
function activateList(list){if(selection.value.list!==list)selection.value={list,ids:[],anchor:null}}
function allSelected(list){const ids=(list==='en'?enabledView.value:availableView.value).map(m=>m.id);return selection.value.list===list&&ids.length>0&&ids.every(id=>selection.value.ids.includes(id))}
function selectAll(list,force=false){selection.value=toggleAll(selection.value,list,(list==='en'?enabledView.value:availableView.value).map(m=>m.id),force);(list==='en'?onList.value:offList.value)?.focus({preventScroll:true})}
function edit(mode){sheetMode.value=mode;name.value=mode==='new'?'新方案':mode==='clone'?`${current.value.name} 副本`:current.value?.name||'';sheet.value='name';menu.value=false}
async function perform(fn){if(busy.value)return;const token=epoch;busy.value=true;error.value='';try{const result=await fn();return token===epoch&&!disposed?result:null}catch(e){if(token===epoch)error.value=e.message;return null}finally{if(token===epoch)busy.value=false}}
async function saveName(){const mode=sheetMode.value;const value=await perform(()=>request(mode==='rename'?'native.profile.update':'native.profile.create',{...(mode==='rename'?{profile_id:selected.value}:{}),name:name.value.trim(),enabled_ids:mode==='new'?[...props.currentOrder]:[...order.value]}));if(value){sheet.value=null;base.value=[...order.value];await refresh(value.id || value.profile?.id || selected.value);notice.value='方案已保存。'}}
async function save(){if(!current.value||current.value.legacy)return;const r=await perform(()=>request('native.profile.update',{profile_id:selected.value,name:current.value.name,enabled_ids:[...order.value]}));if(r){base.value=[...order.value];past.value=[];future.value=[];notice.value='方案已保存；尚未改动游戏。';await refresh()}}
async function apply(){
  if(!current.value||current.value.legacy)return
  const r=await perform(async()=>{const value=await request('native.profile.preview',{profile_id:selected.value});const rules=await request('native.rules.read');return {...value,rules_revision:rules.revision,rules_changed:JSON.stringify(rules.rules)!==JSON.stringify(value.profile?.rules||[])}})
  if(!r)return
  preview.value=r
  if(props.workspaceDirty||r.blocking||r.missing_ids?.length||r.source_changes?.length||r.rules_changed){sheet.value='apply';return}
  await loadPreview()
}
async function loadPreview(){
  if(!preview.value)return
  const p=preview.value
  if(p.rules_changed){const saved=await perform(()=>request('native.rules.save',{expected_revision:p.rules_revision,rules:p.profile.rules||[]}));if(!saved)return}
  emit('apply',p.enabled_ids);sheet.value=null;notice.value='已载入模组草稿，保存后才会写入游戏。'
}
async function migration(){const r=await perform(()=>request('native.profile.preview',{profile_id:selected.value}));if(r){preview.value=r;sheet.value='migration'}}
async function importProfile(){const r=await perform(()=>request('native.profile.import.choose'));if(r&&!r.cancelled){imported.value=r;name.value=r.profile?.name||'导入的方案';sheet.value='import'}}
async function commitImport(){const r=await perform(()=>request('native.profile.import.commit',{source_handle:imported.value.source_handle,name:name.value.trim(),enabled_ids:imported.value.enabled_ids || imported.value.profile.enabled_ids}));if(r){sheet.value=null;base.value=[...order.value];await refresh(r.profile?.id || r.id);notice.value='方案已导入，没有改动游戏。'}}
async function exportProfile(mode){menu.value=false;const r=await perform(()=>request('native.profile.export',{profile_id:selected.value,kind:mode==='file'?'file':'text'}));if(!r)return;if(mode==='file'){notice.value=r.saved?'方案清单已导出。':'已取消导出。';return}text.value=r.text;sheet.value='text';if(mode==='copy')try{await navigator.clipboard.writeText(r.text);notice.value='已复制方案清单；不包含模组文件或批准记录。'}catch{notice.value='请在面板中选择清单文字复制。'}}
async function remove(){const r=await perform(()=>request('native.profile.delete',{profile_id:selected.value}));if(r){sheet.value=null;base.value=[...order.value];await refresh(null);notice.value='方案已删除，恢复副本保留。'}}
function beginDrag(mod,list,e){drag={ids:group(mod.id,list),from:list};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',drag.ids.join(','))}
function drop(list,e){if(!drag||query.value)return;e.preventDefault();const d=drag;drag=null;if(list==='en'){const rows=[...e.currentTarget.querySelectorAll('.row')];let at=order.value.length;for(const row of rows){const r=row.getBoundingClientRect();if(e.clientY<r.top+r.height/2){at=order.value.indexOf(row.dataset.id);break}}if(d.from==='en')change(dropSelection(order.value,d.ids,at),'拖动顺序');else{const {add}=dependencies(d.ids,order.value,props.mods);const next=[...order.value];next.splice(at,0,...add);change(next,'启用')}}else if(d.from==='en'){const affected=reverseDependencies(d.ids,order.value,props.mods);if(affected.length){pending.value={kind:'disable',ids:d.ids,affected};sheet.value='reverse'}else change(order.value.filter(id=>!d.ids.includes(id)),'停用')}}
function keyboard(e){if(!props.active||busy.value||sheet.value||current.value?.legacy||/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName))return;const ctrl=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();if(ctrl&&k==='a'){e.preventDefault();selectAll(document.activeElement===offList.value?'avail':document.activeElement===onList.value?'en':selection.value.list,true);return}if(ctrl&&['s','z','y'].includes(k)){e.preventDefault();if(k==='s')void save();else k==='y'||e.shiftKey?redo():undo();return}if(e.altKey&&['ArrowUp','ArrowDown','Home','End'].includes(e.key)&&!query.value){e.preventDefault();change(moveSelection(order.value,selection.value.ids,{ArrowUp:'up',ArrowDown:'down',Home:'top',End:'bottom'}[e.key]),'调整顺序')}if(['Enter','Delete',' '].includes(e.key)&&selection.value.ids.length){e.preventDefault();toggle(selection.value.ids[0])}}
watch(busy,value=>emit('busy',value))
watch(()=>props.installation?.installation_id,()=>{++epoch;items.value=[];selected.value=null;order.value=[];base.value=[];if(props.active)void refresh()})
watch(()=>props.active,v=>{if(v&&!items.value.length)void refresh()},{immediate:true})
onMounted(()=>window.addEventListener('keydown',keyboard));onUnmounted(()=>{disposed=true;++epoch;window.removeEventListener('keydown',keyboard)})
defineExpose({refresh})
</script>
<template>
  <div class="formal-ui"><section class="page on" data-testid="native-profiles"><div class="garden-intro"><div><h1>方案</h1><p>方案记住一组模组的启用状态、顺序和来源，可以随时切换、应用到游戏或分享给别人。</p></div><div class="garden-intro-actions"><button class="garden-btn soft icon sm" title="刷新" :disabled="busy" @click="refresh()"><Icon name="refresh" size="sm"/></button><button class="garden-btn sm" :disabled="busy||!installation" @click="importProfile"><Icon name="import" size="sm"/>导入</button></div></div><div v-if="error" class="garden-notice care" role="alert">{{ error }}</div><div v-if="notice" class="garden-notice" role="status">{{ notice }}</div>
    <div class="pf"><div class="pf-side"><div class="garden-bed-label" style="margin-top:0">我的方案 <span>{{ items.filter(p=>!p.legacy).length }}</span></div><div class="pf-list"><button v-for="p in items" :key="p.id" class="seed" :class="{on:selected===p.id}" @click="select(p.id)"><span class="pk"><Icon :name="p.legacy?'history':'sprout'" size="sm"/></span><span><b>{{ p.name }}</b><small>{{ p.legacy?'旧格式 · 待迁移':`${p.enabled_ids.length} 个启用 · ${dateText(p.updated_at)}` }}</small></span></button></div><button class="seed-new" :disabled="busy||!installation" @click="edit('new')"><Icon name="plus" size="sm"/> 新方案</button></div>
      <div class="garden-card pf-main"><template v-if="!current"><div class="garden-empty"><Icon name="layers" size="lg"/><b>还没有方案</b><span>用当前模组列表创建第一份方案。</span><button class="garden-btn green sm" :disabled="!installation" @click="edit('new')">新方案</button></div></template><template v-else-if="current.legacy"><div class="pf-head"><div><h2>{{ current.name }}</h2><div class="meta"><span class="tg off">旧版方案</span>仅预览迁移</div></div><span class="sp"></span><button class="garden-btn green sm" :disabled="busy" @click="migration">迁移预览</button></div><div class="sign-note" style="margin-top:16px">能核对的原生模组列入迁移预览；MelonMod、裸 DLL 与旧路径会列出不能迁移的原因，不会自动启用。</div></template><template v-else>
        <div class="pf-head"><div><h2>{{ current.name }}</h2><div class="meta"><span class="tg" :class="dirty?'pend':'on'">{{ dirty?'有未保存的修改':'已保存' }}</span>{{ order.length }} 个启用 · {{ available.length }} 个停用</div></div><span class="sp"></span><button class="garden-btn soft icon sm" title="撤销" :disabled="!past.length||busy" @click="undo"><Icon name="undo" size="sm"/></button><button class="garden-btn soft icon sm" title="重做" :disabled="!future.length||busy" @click="redo"><Icon name="redo" size="sm"/></button><template v-if="dirty"><button class="garden-btn sm" :disabled="busy" @click="edit('clone')">另存为…</button><button class="garden-btn green sm" :disabled="busy" @click="save">保存</button></template><button v-else class="garden-btn green sm" :disabled="busy||applied" @click="apply">应用到游戏</button><div style="position:relative"><button class="garden-btn icon sm" title="更多" @click="menu=!menu"><Icon name="more" size="sm"/></button><div v-if="menu" class="menu on pf-menu"><button @click="edit('rename')">重命名</button><button @click="edit('clone')">复制为新方案</button><button @click="change([...currentOrder],'用当前列表覆盖');menu=false">用当前模组列表覆盖</button><hr/><button :disabled="dirty" @click="exportProfile('copy')">复制分享清单<small>只含 ID、顺序和来源</small></button><button :disabled="dirty" @click="exportProfile('file')">导出清单</button><button :disabled="dirty" @click="exportProfile('text')">查看清单内容</button><hr/><button @click="menu=false;emit('recovery')">恢复点…</button><hr/><button class="danger" @click="menu=false;sheet='delete'">删除方案…</button></div></div></div>
        <div style="display:flex;gap:10px;margin-top:14px"><label class="garden-search" style="flex:1;max-width:none"><Icon name="search" size="sm"/><input v-model="query" placeholder="搜索模组名称、版本或来源"/></label><button class="garden-btn sm" @click="query='';$refs.offList?.focus()"><Icon name="plus" size="sm"/>添加模组</button></div>
        <div class="pf-cols"><section class="bed enabled"><div class="bed-head"><h2><Icon name="check-circle" size="sm"/>已启用</h2><span class="sp"></span><button class="garden-link select-all" data-testid="profile-enabled-all" :disabled="!enabledView.length" @click="selectAll('en')">{{ allSelected('en')?'取消全选':'全选' }}</button><span class="bed-count">{{ order.length }}</span></div><div ref="onList" @pointerdown="marquee.start('en',$event)" @focus="activateList('en')" class="bed-list" tabindex="0" role="listbox" aria-label="方案已启用" aria-multiselectable="true" @dragover="!query&&$event.preventDefault()" @drop="drop('en',$event)"><div v-if="selectionBox?.list==='en'" class="selection-box" :style="selectionBox.style"></div><Row v-for="mod in enabledView" :key="mod.id" :mod="mod" enabled simplified :index="order.indexOf(mod.id)" :baseline="base.includes(mod.id)" :selected="selection.list==='en'&&selection.ids.includes(mod.id)" @toggle="toggle(mod.id)" @select="pick(mod,'en',$event)" @pick="pick(mod,'en',{ctrlKey:true})" @details="emit('reveal',mod.id)" @drag="beginDrag(mod,'en',$event)"/><div v-if="!enabledView.length" class="garden-empty">把模组拖到这里启用</div></div></section><section class="bed avail"><div class="bed-head"><h2><Icon name="pause-circle" size="sm"/>已停用</h2><span class="sp"></span><button class="garden-link select-all" data-testid="profile-available-all" :disabled="!availableView.length" @click="selectAll('avail')">{{ allSelected('avail')?'取消全选':'全选' }}</button><span class="bed-count">{{ available.length }}</span></div><div ref="offList" @pointerdown="marquee.start('avail',$event)" @focus="activateList('avail')" class="bed-list" tabindex="0" role="listbox" aria-label="方案已停用" aria-multiselectable="true" @dragover="!query&&$event.preventDefault()" @drop="drop('avail',$event)"><div v-if="selectionBox?.list==='avail'" class="selection-box" :style="selectionBox.style"></div><Row v-for="mod in availableView" :key="mod.id" :mod="mod" simplified :baseline="base.includes(mod.id)" :selected="selection.list==='avail'&&selection.ids.includes(mod.id)" @toggle="toggle(mod.id)" @select="pick(mod,'avail',$event)" @pick="pick(mod,'avail',{ctrlKey:true})" @details="emit('reveal',mod.id)" @drag="beginDrag(mod,'avail',$event)"/><div v-if="!availableView.length" class="garden-empty">把模组拖到这里停用</div></div></section></div>
      </template></div></div>
    <Sheet v-if="sheet==='name'" :title="{new:'新方案',rename:'重命名方案',clone:'复制为新方案'}[sheetMode]" :busy="busy" @close="sheet=null"><label class="profile-name">方案名称<input v-model="name" maxlength="100" autofocus @keydown.enter="name.trim()&&saveName()"/></label><p v-if="error" class="care-note">{{ error }}</p><template #footer><span class="sp"></span><button class="garden-btn sm" :disabled="busy" @click="sheet=null">取消</button><button class="garden-btn green sm" :disabled="busy||!name.trim()" @click="saveName">保存方案</button></template></Sheet>
    <Sheet v-if="sheet==='discard'" title="方案还有未保存的修改" @close="sheet=null"><div class="sign-note">切换方案会放弃当前草稿。</div><template #footer><span class="sp"></span><button class="garden-btn sm" @click="sheet=null">继续编辑</button><button class="garden-btn clay sm" @click="select(pending.id,true);sheet=null">放弃并切换</button></template></Sheet>
    <Sheet v-if="sheet==='reverse'" title="其他模组依赖它" @close="sheet=null"><div class="lst"><div v-for="id in pending.affected" :key="id" class="li">{{ nameOf(byId(id)) }}</div></div><template #footer><span class="sp"></span><button class="garden-btn sm" @click="sheet=null">取消</button><button class="garden-btn green sm" @click="change(order.filter(id=>!pending.ids.includes(id)&&!pending.affected.includes(id)),'一起停用');sheet=null">一起停用</button></template></Sheet>
    <Sheet v-if="sheet==='apply'" title="载入方案到模组草稿" :busy="busy" @close="sheet=null"><div v-if="workspaceDirty" class="sign-note">模组页已有未保存草稿，继续会替换该草稿；仍需在模组页保存后才写入游戏。</div><div v-for="(issue,i) in preview?.issues" :key="i" class="care-note">{{ issue.message || issue.code }}</div><div v-if="preview?.missing_ids?.length" class="care-note">缺少 {{ preview.missing_ids.join('、') }}；载入后需要补齐才能保存。</div><div v-if="preview?.rules_changed" class="mint-note">继续会把方案排序规则保存到管理器并创建恢复点；模组启用和顺序仍需在模组页保存。</div><p v-if="error" class="care-note">{{ error }}</p><div v-if="preview?.source_changes?.length" class="sign-note">来源或版本变化：{{ preview.source_changes.map(x=>x.id||x.mod_id||x).join('、') }}</div><template #footer><span class="sp"></span><button class="garden-btn sm" @click="sheet=null">取消</button><button class="garden-btn green sm" @click="loadPreview" :disabled="busy">载入草稿</button></template></Sheet>
    <Sheet v-if="sheet==='migration'||sheet==='import'" :title="sheet==='migration'||imported?.legacy?'旧方案迁移预览':'导入方案'" :busy="busy" @close="sheet=null"><template v-if="sheet==='migration'||imported?.legacy"><div class="sign-note">只显示能核对的真实原生 ID，不执行旧方案、不猜测裸 DLL 的对应关系。</div><pre class="logline">{{ JSON.stringify(sheet==='migration'?preview:imported,null,2) }}</pre></template><template v-else><label class="profile-name">方案名称<input v-model="name" maxlength="100"/></label><div class="lst"><div v-for="id in imported.enabled_ids||imported.profile.enabled_ids" :key="id" class="li">{{ nameOf(byId(id)) }}<span v-if="!mods.some(m=>m.id===id)" class="tg pend">未安装</span></div></div></template><p v-if="error" class="care-note">{{ error }}</p><template #footer><span class="sp"></span><button class="garden-btn sm" :disabled="busy" @click="sheet=null">关闭</button><button v-if="sheet==='import'&&!imported?.legacy" class="garden-btn green sm" :disabled="busy||!name.trim()" @click="commitImport">导入为新方案</button></template></Sheet>
    <Sheet v-if="sheet==='text'" title="方案清单" subtitle="只包含模组身份、顺序和来源；不包含文件、私人配置或批准记录。" @close="sheet=null"><textarea class="manifest-text" :value="text" readonly aria-label="方案清单" @focus="$event.target.select()"></textarea><template #footer><span class="sp"></span><button class="garden-btn sm" @click="sheet=null">关闭</button></template></Sheet>
    <Sheet v-if="sheet==='delete'" title="删除方案" :busy="busy" @close="sheet=null"><div class="sign-note">删除“{{ current?.name }}”，不改动游戏。管理器保留恢复副本。</div><p v-if="error" class="care-note">{{ error }}</p><template #footer><span class="sp"></span><button class="garden-btn sm" :disabled="busy" @click="sheet=null">取消</button><button class="garden-btn clay sm" :disabled="busy" @click="remove">删除方案</button></template></Sheet>
  </section></div>
</template>
